_choice_auto_key_locate() {
    cat <<-'EOF' | _argc_util_comp_multi ,
cert	Locate a key using DNS CERT
dane	Locate a key using DANE
wkd	Locate a key using the Web Key Directory protocol
ldap	Locate the key using the configured LDAP servers
ntds	Locate the key using the Active Directory
keyserver	Locate a key using a keyserver
local	Locate the key using the local keyrings
nodefault	Disable the standard local key lookup
clear	Clear all defined mechanisms
EOF
}

_choice_public_key() {
    _helper_key_candidates --list-keys
}

_choice_secret_key() {
    _helper_key_candidates --list-secret-keys
}

_choice_tofu_policy() {
    printf '%s\n' auto good unknown bad ask
}

_helper_key_candidates() {
    gpg --batch --with-colons "$1" 2>/dev/null | gawk -F: '
        $1 == "pub" || $1 == "sec" {
            key = $5
            validity = $2
            next
        }
        $1 == "uid" && key != "" {
            user_id = $10
            desc = user_id
            if (validity == "e") {
                desc = desc " [expired]"
            } else if (validity == "r") {
                desc = desc " [revoked]"
            } else if (validity == "d") {
                desc = desc " [disabled]"
            }
            printf "%s\t%s\n", key, desc
            if (match(user_id, /<[^>]*>/)) {
                email = substr(user_id, RSTART + 1, RLENGTH - 2)
                if (email != "") {
                    printf "%s\t%s\n", email, desc
                }
            }
            key = ""
        }
    '
}
